SELECT 
FROM chat_attachment
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND message_id = #{messageId}
  AND status = 'ATTACHED'
ORDER BY position ASC

SELECT 
FROM chat_attachment
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
  AND status = 'ATTACHED'
  AND message_id = (
    SELECT MAX(m.id)
    FROM chat_message m
    INNER JOIN conversation c ON c.id = m.conversation_id AND c.user_id = #{userId}
    WHERE m.conversation_id = #{conversationId}
      AND m.role = 'user'

        AND m.id <= #{atOrBeforeMessageId}

      AND EXISTS (
        SELECT 1 FROM chat_attachment a
        WHERE a.message_id = m.id AND a.user_id = #{userId}
          AND a.conversation_id = #{conversationId} AND a.status = 'ATTACHED'
      )
  )
ORDER BY position ASC

SELECT 
FROM chat_attachment
WHERE user_id = #{userId}
  AND id IN

      #{id}

SELECT 
FROM chat_attachment
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1
